      "the accumulation of scarce feathers and labor turns the cape into an embodied index of chiefly authority rather than simple decoration; this reading is supported by high-ranking Hawaiian ali‘i controlled tribute networks and specialist production that gathered enormous quantities of valued feathers and by the fact that brilliant red and yellow feathers form broad geometric fields across a semicircular cape designed to surround the wearer."
