// Preserve atomic-set identity after JSON materialization: every question in a
// stimulusGroupId references the same stimulus object, matching the repo-wide
// release invariant used by the generic audit and browser-effective layered banks.
(()=>{const shared=new Map();window.QUESTIONS_AP_ART_HISTORY.forEach(q=>{if(!q.stimulusGroupId||!q.stimulus)return;if(!shared.has(q.stimulusGroupId))shared.set(q.stimulusGroupId,q.stimulus);else q.stimulus=shared.get(q.stimulusGroupId);});})();
